import test from 'node:test';
import assert from 'node:assert/strict';
import {newGame,join,spectate,start,act,view,kill,poisoned,impaired,beginNight,advanceNight,endDay,tick,seen,COUNTS} from '../lib/engine.mjs';
import {ROLES} from '../lib/characters.mjs';
import './accounts.test.mjs';
import './leaderboard.test.mjs';
function game(roles=['chef','soldier','slayer','poisoner','imp']){const g=newGame('ABCDEFGH','P0','s0');for(let i=1;i<roles.length;i++)join(g,`P${i}`,`s${i}`);start(g,roles);return g;}
function choose(g,targets){const q=g.pending;act(g,g.players.find(p=>p.id===q.id).session,{type:'night',key:q.key,targets:targets.map(n=>g.players[n].id)});dawnNow(g);}
// Ending a game early takes a majority vote; everyone but the host agrees here.
function voteToLobby(g){act(g,g.players[1].session,{type:'propose',kind:'lobby'});g.players.slice(2).forEach(p=>{if(g.proposal)act(g,p.session,{type:'proposal_vote',proposal:g.proposal.id,yes:true});});assert.equal(g.phase,'lobby');}
function finishNight(g){let n=0;while(g.phase==='night'&&g.pending&&n++<30){const q=g.pending;let choices=g.players.filter(p=>!q.notSelf||p.id!==q.id).slice(0,q.count);act(g,g.players.find(p=>p.id===q.id).session,{type:'night',key:q.key,targets:choices.map(p=>p.id)});}return dawnNow(g);}
// Dawn comes 5–15 seconds after the last night choice; tests skip ahead to it.
function dawnNow(g){if(g.phase==='night'&&!g.pending&&g.dawnAt)tick(g,g.dawnAt);return g;}
function daytime(g){finishNight(g);assert.equal(g.phase,'day');return g;}
test('standard setup and Baron counts for every supported population',()=>{for(let n=5;n<=15;n++)for(let run=0;run<15;run++){const g=newGame('ABCDEFGH','P0','s0');for(let i=1;i<n;i++)join(g,`P${i}`,`s${i}`);start(g);const actual=t=>g.players.filter(p=>ROLES[p.role].type===t).length;const baron=g.players.some(p=>p.role==='baron')?2:0;assert.equal(actual('townsfolk'),COUNTS[n][0]-baron);assert.equal(actual('outsider'),COUNTS[n][1]+baron);assert.equal(actual('minion'),COUNTS[n][2]);assert.equal(actual('demon'),1);assert.equal(new Set(g.players.map(p=>p.shown)).size,n);assert.equal(g.bluffs.length,3);for(const b of g.bluffs)assert(!g.players.some(p=>p.role===b||p.shown===b));}});
test('Drunk identity and all other secrets stay server-side',()=>{const g=game(['drunk','soldier','slayer','baron','imp']);const v=view(g,'s0');assert.notEqual(v.me.role,'drunk');assert(!('redHerring' in v));assert(!('decisions' in v));for(const p of v.players){assert(!('session' in p));assert(!('role' in p));}assert.throws(()=>view(g,'stranger'));});
test('whispers are visible only to participants',()=>{const g=daytime(game());act(g,'s0',{type:'chat',text:'secret',to:g.players[1].id});assert.equal(view(g,'s1').messages.length,1);assert.equal(view(g,'s2').messages.length,0);});
test('only host starts; late joining is forbidden',()=>{const g=newGame('ABCDEFGH','A','a');join(g,'B','b');assert.throws(()=>act(g,'b',{type:'start'}));assert.throws(()=>act(g,'a',{type:'start'}));const h=game();assert.throws(()=>join(h,'Late','late'));});
test('small games do not get evil introductions',()=>{const g=game();assert(!g.players[4].inbox.some(i=>i.text.includes('Safe bluffs')));const h=game(['chef','soldier','slayer','empath','virgin','poisoner','imp']);assert(h.players[6].inbox.some(i=>i.text.includes('Safe bluffs')));});
test('night action belongs only to requested player and stale requests fail',()=>{const g=game();assert.equal(view(g,'s0').pending,null);assert.equal(view(g,'s3').pending.role,'poisoner');assert.throws(()=>act(g,'s0',{type:'night',key:g.pending.key,targets:[g.players[0].id]}));const old=g.pending.key;choose(g,[0]);assert.throws(()=>act(g,'s3',{type:'night',key:old,targets:[g.players[0].id]}));});
test('Poisoner death and character change clear persistent poisoning',()=>{const g=game();choose(g,[0]);assert(poisoned(g,g.players[0]));kill(g,g.players[3],'slayer');assert(!poisoned(g,g.players[0]));const h=game();choose(h,[0]);h.players[3].role='imp';assert(!poisoned(h,h.players[0]));});
test('healthy Chef exact adjacent pair count',()=>{const g=game(['chef','soldier','slayer','baron','imp']);assert.match(g.players[0].inbox[0].text,/1 neighboring/);});
test('Slayer kill resolves mandatory Scarlet Woman succession',()=>{const g=daytime(game(['slayer','soldier','chef','scarlet_woman','imp']));act(g,'s0',{type:'slayer',target:g.players[4].id});assert.equal(g.players[3].role,'imp');assert.equal(g.phase,'day');assert.equal(g.players[4].alive,false);});
test('Demon death with no successor immediately gives good victory',()=>{const g=daytime(game());g.poison=null;act(g,'s2',{type:'slayer',target:g.players[4].id});assert.equal(g.winner,'good');});
test('poisoned Slayer spends shot without killing',()=>{const g=game();choose(g,[2]);act(g,'s2',{type:'slayer',target:g.players[4].id});assert(g.players[4].alive);assert(g.players[2].slayerUsed);assert.throws(()=>act(g,'s2',{type:'slayer',target:g.players[4].id}));});
test('fake Slayer action is available to everyone',()=>{const g=daytime(game());act(g,'s1',{type:'slayer',target:g.players[4].id});assert(g.players[4].alive);assert(g.events.some(e=>e.text==='Nothing happens.'));});
test('Virgin executes healthy Townsfolk nominator and ends day',()=>{const g=daytime(game(['chef','virgin','soldier','baron','imp']));act(g,'s0',{type:'nominate',target:g.players[1].id});assert(!g.players[0].alive);assert(g.players[1].virginUsed);assert.equal(g.day,2);});
test('Drunk cannot trigger Virgin as a Townsfolk nominator',()=>{const g=daytime(game(['drunk','virgin','soldier','baron','imp']));act(g,'s0',{type:'nominate',target:g.players[1].id});assert(g.players[0].alive);assert(g.players[1].virginUsed);assert(g.nomination);});
test('Saint only loses if alive and healthy at execution death',()=>{const g=daytime(game(['saint','soldier','chef','poisoner','imp']));g.poison=null;kill(g,g.players[0],'execution');assert.equal(g.winner,'evil');const h=daytime(game(['saint','soldier','chef','poisoner','imp']));kill(h,h.players[0],'execution');assert.notEqual(h.phase,'ended');});
test('dead execution consumes day but does not retrigger Saint',()=>{const g=daytime(game(['saint','soldier','chef','baron','imp']));kill(g,g.players[0],'slayer');assert.equal(kill(g,g.players[0],'execution'),false);assert.notEqual(g.phase,'ended');});
test('healthy Soldier survives Imp attack',()=>{const g=daytime(game(['chef','soldier','slayer','baron','imp']));beginNight(g);choose(g,[1]);assert(g.players[1].alive);});
test('Monk cannot choose self and protection prevents Imp self-kill',()=>{const g=daytime(game(['monk','soldier','slayer','baron','imp']));beginNight(g);assert.throws(()=>choose(g,[0]));choose(g,[4]);choose(g,[4]);assert(g.players[4].alive);assert.equal(g.players[3].role,'baron');});
test('Imp starpass changes living Minion and does not attack twice',()=>{const g=daytime(game(['chef','soldier','slayer','baron','imp']));beginNight(g);choose(g,[4]);assert.equal(g.players[3].role,'imp');assert.equal(g.players.filter(p=>!p.alive).length,1);assert.equal(g.phase,'day');});
test('Fortune Teller accepts dead targets and fixed red herring',()=>{const g=game(['fortune_teller','soldier','slayer','baron','imp']);g.redHerring=g.players[1].id;choose(g,[1,2]);assert.match(g.players[0].inbox.at(-1).text,/YES/);g.players[1].alive=false;beginNight(g);choose(g,[1]);choose(g,[1,2]);assert.match(g.players[0].inbox.at(-1).text,/YES/);});
test('Ravenkeeper gets immediate prompt after night death',()=>{const g=daytime(game(['ravenkeeper','soldier','slayer','baron','imp']));beginNight(g);choose(g,[0]);assert.equal(g.pending.role,'ravenkeeper');choose(g,[1]);assert.match(g.players[0].inbox.at(-1).text,/Soldier/);});
test('night death is not public until dawn',()=>{const g=daytime(game(['ravenkeeper','soldier','slayer','baron','imp']));beginNight(g);choose(g,[0]);assert.equal(view(g,'s1').players[0].alive,true);choose(g,[1]);assert.equal(view(g,'s1').players[0].alive,false);});
test('two identical top qualifying tallies cause no execution',()=>{const g=daytime(game());g.ballots=[{target:g.players[0].id,count:3,qualified:true},{target:g.players[1].id,count:3,qualified:true}];endDay(g);assert.equal(g.day,2);assert(g.players.every(p=>p.alive));});
test('ghost vote is spent only when counted and cannot be reused',()=>{const g=daytime(game());g.players[0].alive=false;act(g,'s1',{type:'nominate',target:g.players[2].id});act(g,'s0',{type:'vote',nomination:g.nomination.id,yes:true});assert(g.players[0].ghost);tick(g,g.nomination.deadline+1);assert(!g.players[0].ghost);act(g,'s2',{type:'nominate',target:g.players[1].id});assert.throws(()=>act(g,'s0',{type:'vote',nomination:g.nomination.id,yes:true}));});
test('Mayor wins at three alive without execution, poisoned Mayor does not',()=>{for(const poisonedMayor of [false,true]){const g=daytime(game(['mayor','soldier','chef','poisoner','imp']));g.players[1].alive=false;g.players[2].alive=false;if(!poisonedMayor)g.poison=null;endDay(g);assert.equal(g.winner,poisonedMayor?undefined:'good');}});
test('day and nomination timers respect host pause',()=>{const g=daytime(game());act(g,'s0',{type:'pause'});assert.equal(tick(g,g.deadline+1),false);assert.equal(g.phase,'day');assert.throws(()=>act(g,'s1',{type:'pause'}));act(g,'s0',{type:'pause'});assert.equal(g.paused,false);});
const repeat=(n,fn)=>{for(let i=0;i<n;i++)fn(i);};
test('Drunk Chef never hears an impossible pair count',()=>{repeat(300,()=>{const g=game(['drunk','soldier','slayer','baron','imp']);g.players[0].shown='chef';g.phase='night';g.pending=null;g.queue=[{id:g.players[0].id,role:'chef'}];g.players[0].inbox=[];advanceNight(g);const m=g.players[0].inbox[0].text.match(/(\d+) neighboring/);assert(Number(m[1])<=1,m[0]);});});
test('impaired Chef false counts stay within the evil population',()=>{repeat(300,()=>{const g=newGame('ABCDEFGH','P0','s0');for(let i=1;i<10;i++)join(g,`P${i}`,`s${i}`);start(g,['chef','soldier','slayer','empath','virgin','monk','mayor','poisoner','spy','imp']);choose(g,[0]);const finish=finishNight(g);const m=finish.players[0].inbox.map(i=>i.text).join(' ').match(/(\d+) neighboring/);assert(Number(m[1])<=2,m[0]);});});
test('Washerwoman, Librarian and Investigator never appear in their own pairing or learn their own character',()=>{for(const roles of [['washerwoman','chef','soldier','baron','imp'],['drunk','chef','soldier','poisoner','imp'],['librarian','saint','recluse','poisoner','imp'],['investigator','chef','soldier','poisoner','imp']])repeat(150,()=>{const g=game(roles);finishNight(g);const me=g.players[0],text=me.inbox.map(i=>i.text).join(' ');assert(!text.includes(`${me.name} and`)&&!text.includes(`and ${me.name} is`),text);if(/One of/.test(text))assert(!text.endsWith(`the ${ROLES[me.shown].name}.`),text);});});
test('a Drunk Librarian is not told a table with an Outsider has none',()=>{repeat(200,()=>{const g=game(['drunk','chef','soldier','poisoner','imp']);g.players[0].shown='librarian';g.pending=null;g.queue=[{id:g.players[0].id,role:'librarian'}];g.players[0].inbox=[];advanceNight(g);assert.match(g.players[0].inbox[0].text,/One of/);});});
test('a true Librarian still hears 0 Outsiders',()=>{const g=game(['librarian','chef','soldier','baron','imp']);assert.match(g.players[0].inbox[0].text,/0 Outsiders/);});
test('a lone Townsfolk is never the Washerwoman in a Baron game',()=>{repeat(400,()=>{const g=newGame('ABCDEFGH','P0','s0');for(let i=1;i<5;i++)join(g,`P${i}`,`s${i}`);start(g);const folk=g.players.filter(p=>ROLES[p.role].type==='townsfolk');if(folk.length===1)assert.notEqual(folk[0].role,'washerwoman');});});
test('a Ravenkeeper reading themselves is never told they are the Drunk',()=>{repeat(50,()=>{const g=daytime(game(['drunk','soldier','slayer','baron','imp']));g.players[0].shown='ravenkeeper';beginNight(g);choose(g,[0]);choose(g,[0]);assert.match(g.players[0].inbox.at(-1).text,/is the Ravenkeeper\./);});});
test('Demon bluffs never offer the Drunk, or Outsiders at a table with none',()=>{repeat(200,()=>{const g=newGame('ABCDEFGH','P0','s0');for(let i=1;i<7;i++)join(g,`P${i}`,`s${i}`);start(g);assert.equal(g.bluffs.length,3);assert(g.bluffs.every(b=>ROLES[b].type==='townsfolk'));const h=newGame('ABCDEFGH','P0','s0');for(let i=1;i<9;i++)join(h,`P${i}`,`s${i}`);start(h);assert(!h.bluffs.includes('drunk'));});});
test('one Recluse registers once per Chef reading',()=>{repeat(300,()=>{const g=game(['imp','recluse','baron','chef','soldier']);const n=Number(g.players[3].inbox[0].text.match(/(\d+) neighboring/)[1]);assert(n===0||n===2,`A Recluse between two evil players makes 0 or 2 pairs, not ${n}.`);});});
test('under evil-favoring pressure a Spy usually avoids the Virgin execution',()=>{let executed=0;repeat(300,()=>{const g=daytime(game(['spy','virgin','empath','fortune_teller','undertaker','slayer','chef','monk','mayor','soldier','scarlet_woman','imp']));act(g,'s0',{type:'nominate',target:g.players[1].id});if(!g.players[0].alive)executed++;});assert(executed<120,`Spy executed ${executed}/300 times.`);});
test('group chats are visible only to members and stay out of the town square',()=>{const g=daytime(game());act(g,'s0',{type:'group',title:'Plot',members:[g.players[1].id,g.players[2].id]});const id=g.groups[0].id;act(g,'s0',{type:'chat',text:'hush',group:id});assert.equal(view(g,'s1').messages.at(-1).text,'hush');assert.equal(view(g,'s3').messages.length,0);assert.equal(view(g,'s3').groups.length,0);assert.equal(view(g,'s2').groups[0].title,'Plot');assert.throws(()=>act(g,'s3',{type:'chat',text:'let me in',group:id}));});
test('groups need two others, seated members and a name',()=>{const g=daytime(game());const [a,b]=[g.players[1].id,g.players[2].id];assert.throws(()=>act(g,'s0',{type:'group',title:'Pair',members:[a]}));assert.throws(()=>act(g,'s0',{type:'group',title:'Self',members:[g.players[0].id,a]}));assert.throws(()=>act(g,'s0',{type:'group',title:'Ghost',members:[a,'nobody']}));assert.throws(()=>act(g,'s0',{type:'group',title:' ',members:[a,b]}));});
test('leaving a group ends access to it; the last member closes it',()=>{const g=daytime(game());act(g,'s0',{type:'group',title:'Plot',members:[g.players[1].id,g.players[2].id]});const id=g.groups[0].id;act(g,'s0',{type:'chat',text:'hush',group:id});act(g,'s1',{type:'group_leave',group:id});assert.equal(view(g,'s1').messages.length,0);assert.throws(()=>act(g,'s1',{type:'group_leave',group:id}));act(g,'s0',{type:'group_leave',group:id});act(g,'s2',{type:'group_leave',group:id});assert.equal(g.groups.length,0);});
test('host can kick from the lobby only, and the player may rejoin',()=>{const g=newGame('ABCDEFGH','A','a');join(g,'B','b');join(g,'C','c');const b=g.players[1].id;assert.throws(()=>act(g,'c',{type:'kick',target:b}));assert.throws(()=>act(g,'a',{type:'kick',target:g.host}));act(g,'a',{type:'kick',target:b});assert.equal(g.players.length,2);assert.throws(()=>view(g,'b'));join(g,'B','b');assert.equal(g.players.length,3);const h=daytime(game());assert.throws(()=>act(h,'s0',{type:'kick',target:h.players[1].id}));});
test('kicking removes the player from lobby groups',()=>{const g=newGame('ABCDEFGH','A','a');join(g,'B','b');join(g,'C','c');act(g,'a',{type:'group',title:'Plot',members:[g.players[1].id,g.players[2].id]});act(g,'a',{type:'kick',target:g.players[1].id});assert.equal(g.groups[0].members.length,2);});
test('new game keeps the room, seats and host but clears the last story',()=>{const g=daytime(game());const ids=g.players.map(p=>p.id),host=g.host;act(g,'s0',{type:'chat',text:'old'});act(g,'s0',{type:'group',title:'Plot',members:[ids[1],ids[2]]});g.poison=null;kill(g,g.players[4],'execution');assert.equal(g.phase,'ended');assert.throws(()=>act(g,'s1',{type:'rematch'}));act(g,'s0',{type:'rematch'});assert.equal(g.code,'ABCDEFGH');assert.equal(g.round,2);assert.equal(g.phase,'lobby');assert.equal(g.host,host);assert.deepEqual(g.players.map(p=>p.id),ids);const v=view(g,'s1');assert.equal(v.messages.length,0);assert.equal(v.groups.length,0);assert.equal(v.me.inbox.length,0);assert.equal(v.winner,undefined);assert.equal(v.day,0);assert(g.players.every(p=>p.alive&&p.ghost&&!p.role&&!p.claim));start(g);assert.notEqual(g.phase,'lobby');assert.equal(g.day,1);});
test('a majority vote resets a game in progress, day or night, and a latecomer can then join',()=>{for(const g of [daytime(game()),game(['chef','soldier','slayer','poisoner','imp'])]){const ids=g.players.map(p=>p.id);assert.throws(()=>act(g,'s1',{type:'rematch'}));assert.throws(()=>act(g,'s0',{type:'rematch'}));voteToLobby(g);assert.equal(g.phase,'lobby');assert.equal(g.code,'ABCDEFGH');assert.deepEqual(g.players.map(p=>p.id),ids);assert.equal(g.pending,null);assert.equal(view(g,'s1').interrupted,true);assert(g.players.every(p=>!p.role&&p.alive));join(g,'Late','late');assert.equal(g.players.length,6);start(g);assert(g.players.every(p=>p.role));assert.equal(view(g,'s1').interrupted,undefined);}});
test('reset rerolls roles and cannot fire from the lobby',()=>{const g=newGame('ABCDEFGH','P0','s0');for(let i=1;i<7;i++)join(g,`P${i}`,`s${i}`);assert.throws(()=>act(g,'s0',{type:'rematch'}));const deals=new Set();repeat(30,()=>{start(g);deals.add(g.players.map(p=>p.role).join());g.players.forEach(p=>{p.proposedAt=0;});voteToLobby(g);});assert(deals.size>1);});
const attackMayor=(roles,dead=[])=>{const g=daytime(game(roles));dead.forEach(i=>{g.players[i].alive=false;});beginNight(g);while(g.pending?.role!=='imp')choose(g,[g.players.findIndex(p=>p.role==='virgin')]);choose(g,[0]);finishNight(g);return g;};
test('Mayor attack at the final three is never overruled',()=>{repeat(50,()=>{const g=attackMayor(['mayor','soldier','virgin','baron','imp'],[1,2]);assert.equal(g.players[0].alive,false);assert.equal(g.winner,'evil');});});
test('Mayor attack at four alive either lands or costs evil, never good information',()=>{const seen=new Set();repeat(200,()=>{const g=attackMayor(['mayor','empath','soldier','virgin','baron','imp'],[2,3]);assert(g.players[1].alive&&g.players[5].alive);const died=g.players.filter((p,i)=>!p.alive&&i!==2&&i!==3).map(p=>p.role);assert.equal(died.length,1);seen.add(died[0]);});assert.deepEqual([...seen].sort(),['baron','mayor']);});
test('Mayor redirect in a big town follows who needs the help',()=>{const seen=new Set();repeat(200,()=>{const g=attackMayor(['mayor','empath','ravenkeeper','soldier','virgin','monk','baron','imp']);assert(g.players[0].alive,'A healthy town has someone better to lose.');const died=g.players.filter(p=>!p.alive).map(p=>p.role);assert.equal(died.length,1);seen.add(died[0]);});assert.deepEqual([...seen].sort(),['empath','ravenkeeper']);});
test('a message keeps its client id, trimmed to size',()=>{const g=daytime(game());act(g,'s0',{type:'chat',text:'hi',cid:'x'.repeat(99)});assert.equal(g.messages[0].cid.length,40);g.players[0].lastMessage=0;act(g,'s0',{type:'chat',text:'hi',cid:{bad:1}});assert.equal(g.messages[1].cid,null);});
test('the final reveal has each initial character after a star pass',()=>{const g=daytime(game(['chef','soldier','slayer','baron','imp']));beginNight(g);choose(g,[4]);assert.equal(g.players[3].role,'imp');g.poison=null;kill(g,g.players[3],'execution');assert.equal(g.phase,'ended');const v=view(g,'s0');assert.equal(v.players[3].initialRole,'baron');assert.equal(v.players[4].initialRole,'imp');assert.equal(v.players.filter(p=>p.initialRole==='imp').length,1);});
test('the final reveal has the character a Drunk believed in',()=>{const g=daytime(game(['drunk','soldier','slayer','baron','imp']));const believed=g.players[0].shown;kill(g,g.players[4],'execution');const p=view(g,'s0').players[0];assert.equal(p.initialRole,'drunk');assert.equal(p.shown,believed);});
function moonGame(roles,names=[]){const g=newGame('ABCDEFGH',names[0]||'P0','s0');for(let i=1;i<roles.length;i++)join(g,names[i]||`P${i}`,`s${i}`);act(g,'s0',{type:'settings',daySeconds:180,script:'bmr'});start(g,roles);return g;}
function moonDay(g,pickFor=()=>null){let n=0;while(g.phase==='night'&&g.pending&&n++<60){const q=g.pending,me=g.players.find(p=>p.id===q.id),fixed=pickFor(q);const pool=g.players.filter(p=>(!q.notSelf||p!==me)&&(!q.aliveOnly||p.publicAlive)&&(!q.deadOnly||!p.publicAlive)&&p.id!==q.notId).slice(0,q.count);act(g,me.session,fixed==='skip'?{type:'night',key:q.key,skip:true}:{type:'night',key:q.key,targets:(fixed||pool).map(p=>p.id),character:q.character?'fool':undefined});}return dawnNow(g);}
// A Tinker can die at random, so these rule tests keep it drunk.
const moonNext=(g,pickFor)=>{g.players.filter(p=>p.role==='tinker').forEach(p=>g.drunks.push({id:p.id,until:g.day+1}));beginNight(g);return moonDay(g,pickFor);};
test('host picks the game mode and a three-minute day; a new game keeps them',()=>{const g=newGame('ABCDEFGH','A','a');join(g,'B','b');assert.equal(g.settings.script,'tb');assert.throws(()=>act(g,'b',{type:'settings',daySeconds:240,script:'bmr'}));assert.throws(()=>act(g,'a',{type:'settings',daySeconds:240,script:'nope'}));act(g,'a',{type:'settings',daySeconds:180,script:'bmr'});assert.equal(g.settings.daySeconds,180);assert.equal(g.settings.script,'bmr');for(let i=2;i<7;i++)join(g,`P${i}`,`s${i}`);start(g);assert(g.players.every(p=>ROLES[p.role].script==='bmr'));voteToLobby(g);assert.equal(g.settings.script,'bmr');assert.equal(g.settings.daySeconds,180);});
test('Bad Moon Rising setup counts, with the Godfather adding or removing one Outsider',()=>{for(let n=5;n<=15;n++)for(let run=0;run<25;run++){const g=newGame('ABCDEFGH','P0','s0');g.settings.script='bmr';for(let i=1;i<n;i++)join(g,`P${i}`,`s${i}`);start(g);const c=t=>g.players.filter(p=>ROLES[p.role].type===t).length;assert(g.players.every(p=>ROLES[p.role].script==='bmr'));assert.equal(new Set(g.players.map(p=>p.role)).size,n);assert.equal(c('minion'),COUNTS[n][2]);assert.equal(c('demon'),1);const delta=c('outsider')-COUNTS[n][1];assert(g.players.some(p=>p.role==='godfather')?Math.abs(delta)===1:delta===0);assert.equal(c('townsfolk'),COUNTS[n][0]-delta);assert(!g.bluffs.includes('lunatic'));assert.equal(g.bluffs.length,3);}});
test('Trouble Brewing never deals a Bad Moon Rising character',()=>{repeat(40,()=>{const g=newGame('ABCDEFGH','P0','s0');for(let i=1;i<15;i++)join(g,`P${i}`,`s${i}`);start(g);assert(g.players.every(p=>ROLES[p.role].script==='tb'));});});
test('a player with too few legal targets is skipped instead of freezing the night',()=>{const g=moonGame(['chambermaid','minstrel','tinker','mastermind','zombuul']);moonDay(g);[1,2,3].forEach(i=>{g.players[i].alive=false;});g.diedToday=true;g.queue=[];g.players.forEach(p=>{p.publicAlive=p.alive;});g.phase='night';g.queue=[{id:g.players[0].id,role:'chambermaid'}];g.pending=null;advanceNight(g);assert.equal(g.pending,null);dawnNow(g);assert.equal(g.phase,'day');});
test('Pukka poisons on the first night and kills the previous target later',()=>{const g=moonGame(['chambermaid','minstrel','tinker','assassin','pukka']);moonDay(g,q=>q.role==='pukka'?[g.players[1]]:null);assert.equal(g.players.filter(p=>!p.alive).length,0);assert(poisoned(g,g.players[1]));moonNext(g,q=>q.role==='pukka'?[g.players[0]]:q.role==='assassin'?'skip':null);assert(!g.players[1].alive);assert(g.players[0].alive);assert(poisoned(g,g.players[0]));});
test('a drunk Pukka freezes its poison instead of killing',()=>{const g=moonGame(['chambermaid','minstrel','tinker','assassin','pukka']);moonDay(g,q=>q.role==='pukka'?[g.players[1]]:null);g.drunks.push({id:g.players[4].id,until:99});moonNext(g,q=>q.role==='pukka'?[g.players[0]]:q.role==='assassin'?'skip':null);assert(g.players[1].alive);assert.equal(g.poison.target,g.players[1].id);});
test('the first time the Fool would die, they do not',()=>{const g=moonGame(['fool','minstrel','tinker','assassin','zombuul']);moonDay(g);g.phase='day';kill(g,g.players[0],'night');assert(g.players[0].alive);kill(g,g.players[0],'night');assert(!g.players[0].alive);});
test('a sober Sailor cannot die, even by execution; the Assassin ignores that',()=>{const g=moonGame(['sailor','minstrel','tinker','assassin','zombuul']);moonDay(g,q=>q.role==='sailor'?[g.players[0]]:null);g.drunks=[];assert.equal(kill(g,g.players[0],'execution'),false);assert.equal(kill(g,g.players[0],'night',false,{force:true}),true);});
test('a Sailor who picks themself is drunk and can die',()=>{const g=moonGame(['sailor','minstrel','tinker','assassin','zombuul']);moonDay(g,q=>q.role==='sailor'?[g.players[0]]:null);assert(impaired(g,g.players[0]));g.phase='day';kill(g,g.players[0],'night');assert(!g.players[0].alive);});
test('an Innkeeper made drunk by their own ability protects nobody, and is the likely one to get drunk',()=>{let drunkSelf=0;const runs=300;for(let i=0;i<runs;i++){const g=moonGame(['innkeeper','minstrel','pacifist','assassin','zombuul']);moonDay(g);moonNext(g,q=>q.role==='innkeeper'?[g.players[0],g.players[1]]:q.role==='zombuul'?[g.players[1]]:q.role==='assassin'?'skip':null);const self=g.drunks.some(d=>d.id===g.players[0].id);if(self)drunkSelf++;assert.equal(g.players[1].alive,!self);}assert(drunkSelf>runs/2,`Innkeeper drunk in only ${drunkSelf} of ${runs}`);assert(drunkSelf<runs);});
test('a Sailor poisoned by the Pukka dies the next night, still poisoned',()=>{const g=moonGame(['sailor','minstrel','pacifist','assassin','pukka']);moonDay(g,q=>['pukka','sailor'].includes(q.role)?[g.players[0]]:null);moonNext(g,q=>q.role==='pukka'?[g.players[1]]:q.role==='sailor'?[g.players[0]]:q.role==='assassin'?'skip':null);assert.equal(g.players[0].alive,false);assert.equal(g.poison.target,g.players[1].id);});
test('Innkeeper protects both picks for the night and makes one drunk until dusk',()=>{const g=moonGame(['innkeeper','minstrel','pacifist','assassin','zombuul']);moonDay(g);moonNext(g,q=>q.role==='innkeeper'?[g.players[1],g.players[2]]:q.role==='zombuul'?[g.players[1]]:q.role==='assassin'?'skip':null);assert(g.players[1].alive);assert.equal(g.drunks.filter(d=>[g.players[1].id,g.players[2].id].includes(d.id)).length,1);beginNight(g);assert.equal(g.drunks.length,0);});
test('Tea Lady guards two good neighbours but not an evil-flanked table',()=>{const g=moonGame(['tea_lady','minstrel','tinker','assassin','zombuul']);moonDay(g);assert.equal(kill(g,g.players[1],'night'),true);assert(!g.players[1].alive);const h=moonGame(['tinker','tea_lady','minstrel','assassin','zombuul']);moonDay(h);assert.equal(kill(h,h.players[0],'night'),false);assert(h.players[0].alive);});
test('Zombuul appears dead once, keeps acting, and the game goes on',()=>{const g=moonGame(['chambermaid','minstrel','tinker','assassin','zombuul']);moonDay(g);g.phase='day';kill(g,g.players[4],'execution');assert.equal(g.players[4].alive,false);assert.equal(g.players[4].zombuulUp,true);assert.notEqual(g.phase,'ended');assert(g.diedToday);g.diedToday=false;moonNext(g,q=>q.role==='assassin'?'skip':q.role==='zombuul'?[g.players[0]]:null);assert(!g.players[0].alive);g.phase='day';assert.equal(kill(g,g.players[4],'execution'),true);assert.equal(g.winner,'good');});
test('Zombuul does not wake if someone died today',()=>{const g=moonGame(['chambermaid','minstrel','tinker','assassin','zombuul']);moonDay(g);g.phase='day';kill(g,g.players[2],'execution');beginNight(g);const seen=[];let n=0;while(g.pending&&n++<20){seen.push(g.pending.role);const q=g.pending;act(g,g.players.find(p=>p.id===q.id).session,q.optional?{type:'night',key:q.key,skip:true}:{type:'night',key:q.key,targets:g.players.filter(p=>p.publicAlive&&p.id!==q.id).slice(0,q.count).map(p=>p.id)});}assert(!seen.includes('zombuul'));});
test('a Zombuul that looks dead still counts for the two-alive check',()=>{const g=moonGame(['chambermaid','minstrel','tinker','assassin','zombuul']);moonDay(g);g.phase='day';kill(g,g.players[4],'execution');[1,2].forEach(i=>kill(g,g.players[i],'night'));assert.notEqual(g.phase,'ended');assert.equal(g.players.filter(p=>p.alive).length,2);});
test('Po charges up by choosing nobody and then takes three',()=>{const g=moonGame(['chambermaid','minstrel','tinker','fool','tea_lady','assassin','po']);moonDay(g);moonNext(g,q=>['po','assassin'].includes(q.role)?'skip':null);assert(g.players.every(p=>p.alive));beginNight(g);let n=0;while(g.pending?.role!=='po'&&n++<9){const q=g.pending;act(g,g.players.find(p=>p.id===q.id).session,q.optional?{type:'night',key:q.key,skip:true}:{type:'night',key:q.key,targets:g.players.filter(p=>p.id!==q.id&&p.publicAlive).slice(0,q.count).map(p=>p.id)});}assert.equal(g.pending.count,3);});
test('a drunk Po who takes three still spends the charge, so the next night is one choice',()=>{const g=moonGame(['chambermaid','minstrel','tinker','fool','tea_lady','assassin','po']);moonDay(g);moonNext(g,q=>['po','assassin'].includes(q.role)?'skip':null);const po=g.players[6];assert(po.poCharged);g.drunks.push({id:po.id,until:g.day+1});const alive=g.players.filter(p=>p.alive).length;moonNext(g,q=>q.role==='po'?g.players.slice(0,3):q.role==='assassin'?'skip':null);assert.equal(g.players.filter(p=>p.alive).length,alive);assert.equal(po.poCharged,false);beginNight(g);let n=0;while(g.pending?.role!=='po'&&n++<9){const q=g.pending;act(g,g.players.find(p=>p.id===q.id).session,q.optional?{type:'night',key:q.key,skip:true}:{type:'night',key:q.key,targets:g.players.filter(p=>p.id!==q.id&&p.publicAlive).slice(0,q.count).map(p=>p.id)});}assert.equal(g.pending.count,1);});
test('a drunk Po who chooses nobody still charges up',()=>{const g=moonGame(['chambermaid','minstrel','tinker','fool','tea_lady','assassin','po']);moonDay(g);const po=g.players[6];g.drunks.push({id:po.id,until:g.day+1});moonNext(g,q=>['po','assassin'].includes(q.role)?'skip':null);assert(po.poCharged);});
test('the Courtier’s drunkenness pauses while the Courtier is drunk, comes back when they recover, and ends when they die',()=>{const g=moonGame(['courtier','fool','chambermaid','assassin','zombuul']);moonDay(g);const [courtier,fool]=g.players;assert(impaired(g,fool));g.drunks.push({id:courtier.id,until:g.day+5});assert(!impaired(g,fool));g.drunks.pop();assert(impaired(g,fool));courtier.alive=false;assert(!impaired(g,fool));});
test('a drunk Courtier’s choice does nothing, even after they sober up',()=>{const g=moonGame(['courtier','fool','chambermaid','assassin','zombuul']);const [courtier,fool]=g.players;g.drunks.push({id:courtier.id,until:g.day});moonDay(g);g.drunks=g.drunks.filter(d=>d.id!==courtier.id);assert(!impaired(g,courtier));assert(!impaired(g,fool));});
test('a Courtier who names their own character is drunk',()=>{const g=moonGame(['courtier','fool','chambermaid','assassin','zombuul']);const courtier=g.players[0];g.drunks.push({id:courtier.id,until:g.day+2,source:courtier.id});assert(impaired(g,courtier));});
// Plays a night to dawn, answering each prompt with pick(q, me): an array of players, 'skip', or null for the first legal players.
function playNight(g,pick){let n=0;while(g.phase==='night'&&g.pending&&n++<40){const q=g.pending,me=g.players.find(p=>p.id===q.id),chosen=pick(q,me);if(chosen==='skip'){act(g,me.session,{type:'night',key:q.key,skip:true});continue;}if(chosen?.character){act(g,me.session,{type:'night',key:q.key,targets:[],character:chosen.character});continue;}const pool=g.players.filter(p=>(!q.notSelf||p!==me)&&(!q.aliveOnly||p.publicAlive)&&(!q.deadOnly||!p.publicAlive)&&p.id!==q.notId).slice(0,q.count);act(g,me.session,{type:'night',key:q.key,targets:(chosen||pool).map(p=>p.id),character:q.character?'fool':undefined});}dawnNow(g);}
test('the Minstrel makes everyone else drunk when a Minion is executed, but not themself',()=>{const g=moonGame(['minstrel','chambermaid','fool','assassin','zombuul']);moonDay(g);kill(g,g.players[3],'execution');assert(!impaired(g,g.players[0]));assert(impaired(g,g.players[1]));assert(impaired(g,g.players[4]));});
test('a charged Po must choose three and cannot choose nobody',()=>{const g=moonGame(['chambermaid','minstrel','fool','tea_lady','assassin','po']);moonDay(g);moonNext(g,q=>['po','assassin'].includes(q.role)?'skip':null);beginNight(g);let n=0;while(g.pending?.role!=='po'&&n++<9){const q=g.pending;act(g,g.players.find(p=>p.id===q.id).session,q.optional?{type:'night',key:q.key,skip:true}:{type:'night',key:q.key,targets:g.players.filter(p=>p.id!==q.id&&p.publicAlive).slice(0,q.count).map(p=>p.id)});}assert.equal(g.pending.count,3);assert.equal(g.pending.optional,false);assert.throws(()=>act(g,'s5',{type:'night',key:g.pending.key,skip:true}));});
test('a Courtier who names the Goon is drunk, and the Goon joins their team',()=>{const g=moonGame(['courtier','goon','chambermaid','assassin','zombuul']);const [courtier,goon]=g.players;playNight(g,q=>q.role==='courtier'?{character:'goon'}:null);assert(impaired(g,courtier));assert(!impaired(g,goon));assert.equal(goon.aligned,'good');});
test('the Assassin still kills the Goon it chooses, though it is made drunk, and a drunk Assassin does not',()=>{
 let g=moonGame(['goon','chambermaid','fool','assassin','zombuul']);moonDay(g);moonNext(g,q=>q.role==='assassin'?[g.players[0]]:q.role==='zombuul'?[g.players[1]]:null);assert(!g.players[0].alive);assert.equal(g.players[0].aligned,'evil');assert(impaired(g,g.players[3]));
 g=moonGame(['goon','chambermaid','fool','assassin','zombuul']);moonDay(g);g.drunks.push({id:g.players[3].id,until:g.day+1});moonNext(g,q=>q.role==='assassin'?[g.players[0]]:q.role==='zombuul'?[g.players[1]]:null);assert(g.players[0].alive);assert.equal(g.players[0].aligned,'evil');});
test('an exorcised Pukka poisons nobody, but last night’s victim still dies',()=>{const g=moonGame(['exorcist','chambermaid','fool','assassin','pukka']);moonDay(g,q=>q.role==='pukka'?[g.players[1]]:null);assert(poisoned(g,g.players[1]));moonNext(g,q=>q.role==='exorcist'?[g.players[4]]:q.role==='assassin'?'skip':null);assert(!g.players[1].alive);assert.equal(g.poison,null);assert(g.players[2].alive);});
test('a player the Professor brings back regains a used once-per-game ability',()=>{const g=moonGame(['professor','courtier','chambermaid','assassin','zombuul']);moonDay(g,q=>q.role==='courtier'?'skip':null);const courtier=g.players[1];courtier.abilityUsed=true;courtier.alive=false;moonNext(g,q=>q.role==='professor'?[courtier]:q.role==='zombuul'?[g.players[2]]:q.optional?'skip':null);assert(courtier.alive);assert.equal(courtier.abilityUsed,false);});
test('a Grandmother brought back learns a grandchild again at once',()=>{const g=moonGame(['professor','grandmother','chambermaid','assassin','zombuul']);moonDay(g);const gran=g.players[1],before=gran.inbox.filter(i=>/grandchild/.test(i.text)).length;gran.alive=false;moonNext(g,q=>q.role==='professor'?[gran]:q.role==='zombuul'?[g.players[2]]:q.optional?'skip':null);assert(gran.alive);assert.equal(gran.inbox.filter(i=>/grandchild/.test(i.text)).length,before+1);});
test('a Moonchild who dies drunk still chooses, and a Goon good when chosen dies even if it turns evil',()=>{
 let g=moonGame(['moonchild','chambermaid','fool','assassin','zombuul']);moonDay(g);g.drunks.push({id:g.players[0].id,until:g.day+1});kill(g,g.players[0],'day');assert(g.players[0].moonPending);
 g=moonGame(['moonchild','goon','chambermaid','assassin','zombuul']);moonDay(g);const goon=g.players[1];kill(g,g.players[0],'day');act(g,'s0',{type:'moonchild',target:goon.id});goon.aligned='evil';moonNext(g,q=>q.role==='assassin'?'skip':null);assert(!goon.alive);});
test('the Storyteller never kills the Tinker when that would end the game',()=>{const g=moonGame(['tinker','chambermaid','fool','assassin','zombuul']);moonDay(g);g.players[1].alive=false;g.players[2].alive=false;g.tinkerAt=Date.now()-1;tick(g,Date.now());assert(g.players[0].alive);assert.notEqual(g.phase,'ended');});
test('the Devil’s Advocate protects for tomorrow only, so a drunk one protects nobody the day after',()=>{const g=moonGame(['chambermaid','fool','minstrel','devils_advocate','zombuul']);const da=g.players[3];moonDay(g,q=>q.role==='devils_advocate'?[g.players[0]]:null);assert.equal(g.advocate.target,g.players[0].id);g.drunks.push({id:da.id,until:g.day+1});moonNext(g,q=>q.role==='devils_advocate'?[g.players[1]]:q.role==='zombuul'?[g.players[2]]:null);g.drunks=g.drunks.filter(d=>d.id!==da.id);assert.equal(kill(g,g.players[0],'execution'),true);assert(!g.players[0].alive);});
test('the Professor wakes even when nobody is dead yet, and can only decline',()=>{const g=moonGame(['professor','chambermaid','fool','assassin','zombuul']);moonDay(g);let woke=false;moonNext(g,q=>{if(q.role==='professor')woke=true;return q.optional?'skip':q.role==='zombuul'?[g.players[2]]:null;});assert(woke);assert.equal(g.players[0].abilityUsed,undefined);});
test('Shabaloth kills two',()=>{const g=moonGame(['chambermaid','minstrel','tinker','pacifist','assassin','shabaloth']);moonDay(g);moonNext(g,q=>q.role==='shabaloth'?[g.players[1],g.players[2]]:q.role==='assassin'?'skip':null);assert.equal(g.players.filter(p=>!p.alive).length,2);});
test('Goon makes its first chooser drunk before they act and joins their team',()=>{const g=moonGame(['goon','minstrel','tinker','assassin','zombuul']);moonDay(g);moonNext(g,q=>q.role==='zombuul'?[g.players[0]]:q.role==='assassin'?'skip':null);assert(g.players[0].alive);assert(impaired(g,g.players[4]));assert.equal(g.players[0].aligned,'evil');});
test('Gambler dies on a wrong guess and lives on a right one',()=>{const g=moonGame(['gambler','minstrel','tinker','assassin','zombuul']);moonDay(g);moonNext(g,q=>q.role==='zombuul'?[g.players[3]]:q.role==='assassin'?'skip':q.role==='gambler'?[g.players[2]]:null);assert(!g.players[0].alive);const h=moonGame(['gambler','fool','tinker','assassin','zombuul']);moonDay(h);moonNext(h,q=>q.role==='zombuul'?[h.players[3]]:q.role==='assassin'?'skip':q.role==='gambler'?[h.players[1]]:null);assert(h.players[0].alive);});
test('Courtier makes the named character drunk for three days',()=>{const g=moonGame(['courtier','minstrel','tinker','assassin','zombuul']);let chosen=false;let n=0;while(g.pending&&n++<9){const q=g.pending;if(q.role==='courtier'){act(g,'s0',{type:'night',key:q.key,targets:[],character:'tinker'});chosen=true;}else act(g,g.players.find(p=>p.id===q.id).session,{type:'night',key:q.key,targets:g.players.filter(p=>p.id!==q.id).slice(0,q.count).map(p=>p.id),character:'fool'});}assert(chosen);assert(impaired(g,g.players[2]));assert(g.players[0].abilityUsed);g.phase='day';beginNight(g);assert.equal(g.day,2);assert(impaired(g,g.players[2]));g.pending=null;g.phase='day';beginNight(g);g.pending=null;assert.equal(g.day,3);assert(impaired(g,g.players[2]));g.phase='day';beginNight(g);assert.equal(g.day,4);assert(!impaired(g,g.players[2]));});
test('Professor brings back only a Townsfolk',()=>{const g=moonGame(['professor','fool','tinker','assassin','zombuul']);moonDay(g);g.phase='day';g.players[1].alive=false;g.players[1].ghost=false;moonNext(g,q=>q.role==='professor'?[g.players[1]]:q.role==='zombuul'?[g.players[3]]:q.role==='assassin'?'skip':null);assert(g.players[1].alive);assert(g.players[1].ghost);const h=moonGame(['professor','minstrel','tinker','assassin','zombuul']);moonDay(h);h.phase='day';h.players[2].alive=false;moonNext(h,q=>q.role==='professor'?[h.players[2]]:q.role==='zombuul'?[h.players[3]]:q.role==='assassin'?'skip':null);assert(!h.players[2].alive);});
test('Chambermaid counts who woke tonight',()=>{const g=moonGame(['chambermaid','minstrel','tinker','assassin','pukka']);moonDay(g,q=>q.role==='chambermaid'?[g.players[4],g.players[1]]:q.role==='pukka'?[g.players[1]]:null);assert.match(g.players[0].inbox.at(-1).text,/1 woke/);});
test('Exorcist stops the Demon waking and tells them who did it',()=>{const g=moonGame(['exorcist','minstrel','tinker','assassin','zombuul']);moonDay(g);moonNext(g,q=>q.role==='exorcist'?[g.players[4]]:q.role==='assassin'?'skip':null);assert(g.players.every(p=>p.alive));assert(g.players[4].inbox.some(i=>/The Exorcist is P0/.test(i.text)));beginNight(g);assert.throws(()=>choose(g,[4]));});
test('Lunatic wakes as a Demon, kills nobody, and the real Demon sees the choice',()=>{const g=moonGame(['chambermaid','minstrel','lunatic','assassin','zombuul']);assert(['zombuul','pukka','shabaloth','po'].includes(g.players[2].shown));assert(g.players[4].inbox.some(i=>/P2 is the Lunatic/.test(i.text)));moonDay(g);g.diedToday=false;moonNext(g,q=>q.role==='assassin'?'skip':q.id===g.players[2].id?(q.count===1?[g.players[1]]:g.players.filter(p=>p!==g.players[2]).slice(0,q.count)):q.role==='zombuul'?[g.players[3]]:null);assert(g.players[1].alive);assert(g.players[4].inbox.some(i=>/The Lunatic chose/.test(i.text)));});
test('Lunatic believes they are the Demon actually in play',()=>{for(const demon of ['zombuul','pukka','shabaloth','po']){const g=moonGame(['chambermaid','minstrel','lunatic','assassin',demon]);assert.equal(g.players[2].shown,demon);}});
test('the Spy sees the Grimoire last, after the night\'s kill',()=>{const g=daytime(game(['soldier','monk','empath','spy','imp']));g.phase='day';beginNight(g);let n=0;while(g.phase==='night'&&n++<9){const q=g.pending;choose(g,q.role==='imp'?[2]:q.role==='monk'?[0]:[1]);}const snap=g.players[3].inbox.filter(i=>i.grimoire).at(-1).grimoire;assert.equal(snap[2].alive,false);});
test('the Courtier acts before the Innkeeper, so a named Innkeeper protects nobody that night',()=>{const g=moonGame(['courtier','innkeeper','minstrel','assassin','zombuul']);moonDay(g,q=>q.role==='courtier'?'skip':null);g.phase='day';beginNight(g);const seen=[];let n=0;while(g.phase==='night'&&g.pending&&n++<20){const q=g.pending,me=g.players.find(p=>p.id===q.id);seen.push(q.role);act(g,me.session,q.role==='courtier'?{type:'night',key:q.key,targets:[],character:'innkeeper'}:q.optional?{type:'night',key:q.key,skip:true}:{type:'night',key:q.key,targets:g.players.filter(p=>p!==me).slice(0,q.count).map(p=>p.id)});}assert(seen.indexOf('courtier')<seen.indexOf('innkeeper'));assert.deepEqual(g.innkeep,[]);});
test('the Professor acts before the Moonchild, so a revived target can still die',()=>{const g=moonGame(['moonchild','professor','minstrel','assassin','zombuul','fool']);moonDay(g,q=>q.optional?'skip':null);g.phase='day';g.players[0].alive=false;g.players[2].alive=false;g.diedToday=true;g.moonTarget={by:g.players[0].id,target:g.players[2].id,good:true};moonNext(g,q=>q.role==='professor'?[g.players[2]]:q.optional?'skip':null);assert.equal(g.players[2].alive,false);assert.equal(g.moonTarget,null);});
test('a Goon only stops the attacks chosen after it',()=>{const run=order=>{const g=moonGame(['chambermaid','minstrel','goon','assassin','shabaloth','fool']);moonDay(g);moonNext(g,q=>q.role==='shabaloth'?order.map(i=>g.players[i]):q.role==='assassin'?'skip':null);return g;};const g=run([0,2]);assert(!g.players[0].alive);assert(g.players[2].alive);assert.equal(g.players[2].aligned,'evil');assert(impaired(g,g.players[4]));const h=run([2,0]);assert(h.players[0].alive);assert(h.players[2].alive);assert.equal(h.players[2].aligned,'evil');});
test('an executed Moonchild chooses that night, and a good target dies',()=>{const g=moonGame(['moonchild','minstrel','fool','assassin','zombuul']);moonDay(g);g.ballots=[{target:g.players[0].id,count:5,qualified:true,votes:[],day:g.day}];endDay(g);assert.equal(g.phase,'night');moonDay(g,q=>q.role==='assassin'?'skip':q.role==='moonchild'?[g.players[1]]:null);assert.equal(g.phase,'day');assert(!g.players[1].alive);assert.equal(g.players[0].moonPending,false);assert(g.events.some(e=>/Moonchild and chooses P1/.test(e.text)));});
test('a Moonchild killed at night only chooses after dawn',()=>{const g=moonGame(['moonchild','minstrel','fool','assassin','zombuul']);moonDay(g);moonNext(g,q=>q.role==='zombuul'?[g.players[0]]:q.role==='assassin'?'skip':null);assert.equal(g.phase,'day');assert(!g.players[0].alive);assert.equal(g.players[0].moonPending,true);});
test('a Lunatic who believes they are the Po charges up like the real one',()=>{const g=moonGame(['chambermaid','minstrel','lunatic','assassin','po','fool']);moonDay(g);moonNext(g,q=>q.optional?'skip':null);g.phase='day';beginNight(g);let n=0;while(g.pending&&g.pending.id!==g.players[2].id&&n++<9){const q=g.pending,me=g.players.find(p=>p.id===q.id);act(g,me.session,q.optional?{type:'night',key:q.key,skip:true}:{type:'night',key:q.key,targets:g.players.filter(p=>p!==me).slice(0,q.count).map(p=>p.id)});}assert.equal(g.pending.count,3);act(g,'s2',{type:'night',key:g.pending.key,targets:[g.players[0].id,g.players[1].id,g.players[3].id]});assert.equal(g.players[2].poCharged,false);});
test('Godfather learns Outsiders, and kills only after an Outsider died today',()=>{const g=moonGame(['chambermaid','minstrel','tinker','godfather','zombuul']);moonDay(g);assert.match(g.players[3].inbox.map(i=>i.text).join(' '),/Tinker/);moonNext(g,q=>q.role==='zombuul'?[g.players[0]]:null);assert.equal(g.pending,null);g.phase='day';kill(g,g.players[2],'execution');assert(g.outsiderDied);beginNight(g);assert.equal(g.pending.role,'godfather');});
test('Devil\'s Advocate saves the execution, once per pick',()=>{const g=moonGame(['chambermaid','minstrel','tinker','devils_advocate','zombuul']);moonDay(g,q=>q.role==='devils_advocate'?[g.players[1]]:null);g.phase='day';assert.equal(kill(g,g.players[1],'execution'),false);beginNight(g);const q=g.pending;assert.equal(q.role,'devils_advocate');assert.equal(q.notId,g.players[1].id);assert.throws(()=>act(g,'s3',{type:'night',key:q.key,targets:[g.players[1].id]}));});
test('Grandmother learns a good grandchild and dies with them to the Demon only',()=>{const g=moonGame(['grandmother','minstrel','tinker','assassin','zombuul']);moonDay(g);const child=g.players.find(p=>p.id===g.players[0].grandchild);assert(!['assassin','zombuul'].includes(child.role));moonNext(g,q=>q.role==='zombuul'?[child]:q.role==='assassin'?'skip':null);assert(!g.players[0].alive);});
test('Minstrel makes everyone else drunk until dusk tomorrow when a Minion is executed',()=>{const g=moonGame(['minstrel','fool','tinker','assassin','zombuul']);moonDay(g);g.phase='day';g.nomination=null;const day=g.day;kill(g,g.players[3],'execution');assert(impaired(g,g.players[1]));assert.equal(g.drunks[0].until,day+1);});
test('Mastermind plays one more day: the executed player\'s team loses, and no execution means good wins',()=>{for(const outcome of ['good-executed','evil-executed','none']){const g=moonGame(['chambermaid','minstrel','tinker','mastermind','zombuul']);moonDay(g);g.players[4].zombuulSpent=true;g.ballots=[{target:g.players[4].id,count:3,qualified:true}];endDay(g);assert.notEqual(g.phase,'ended');assert(g.mastermindDay);moonDay(g);assert.equal(g.phase,'day');assert.equal(g.day,g.mastermindDay);if(outcome==='none'){g.ballots=[];endDay(g);assert.equal(g.winner,'good');}else{const i=outcome==='good-executed'?0:3;g.ballots=[{target:g.players[i].id,count:3,qualified:true}];endDay(g);assert.equal(g.winner,i===0?'evil':'good');}}});
test('a dead Mastermind does not extend the game',()=>{const g=moonGame(['chambermaid','minstrel','tinker','mastermind','zombuul']);moonDay(g);g.players[4].zombuulSpent=true;g.players[3].alive=false;g.phase='day';kill(g,g.players[4],'execution');assert.equal(g.winner,'good');});
test('Moonchild publicly chooses and a good target dies that night',()=>{const g=moonGame(['moonchild','minstrel','tinker','assassin','zombuul']);moonDay(g);g.phase='day';kill(g,g.players[0],'execution');assert.equal(view(g,'s0').me.moonPending,true);g.deadline=Date.now()+99999;assert.throws(()=>act(g,'s1',{type:'moonchild',target:g.players[1].id}));act(g,'s0',{type:'moonchild',target:g.players[1].id});assert(g.events.some(e=>/Moonchild and chooses P1/.test(e.text)));moonNext(g,q=>q.role==='assassin'?'skip':null);assert(!g.players[1].alive);});
function gossipGame(say,names){const g=moonGame(['gossip','minstrel','tinker','assassin','zombuul'],names);moonDay(g);assert.equal(g.phase,'day');g.players[0].lastMessage=0;act(g,'s0',{type:'chat',text:say,statement:true});return g;}
const NAMES=['Ana','Bo','Cy','Dee','Eli'];
test('a statement is a public, tagged Town square message that everyone sees',()=>{const g=gossipGame('Dee is evil',NAMES);for(const s of ['s0','s1','s3']){const m=view(g,s).messages.at(-1);assert.equal(m.statement,true);assert.equal(m.text,'Dee is evil');assert(!JSON.stringify(view(g,s)).includes('"truth"'));}});
test('an ordinary message is not a statement',()=>{const g=moonGame(['gossip','minstrel','tinker','assassin','zombuul'],NAMES);moonDay(g);act(g,'s0',{type:'chat',text:'Dee is evil'});assert.equal(g.messages[0].statement,false);assert.equal(g.gossip,null);assert.equal(view(g,'s0').me.statementUsed,false);});
test('a statement can be made once per day, and again the next day',()=>{const g=gossipGame('Dee is evil',NAMES);assert.equal(view(g,'s0').me.statementUsed,true);g.players[0].lastMessage=0;assert.throws(()=>act(g,'s0',{type:'chat',text:'Eli is evil',statement:true}),/already/);assert.equal(g.gossip.reading,'Dee is evil');g.players[2].alive=true;g.drunks.push({id:g.players[2].id,until:99});g.players[3].role='minstrel';g.diedToday=true;beginNight(g);moonDay(g,q=>q.optional?'skip':null);assert.equal(g.phase,'day');assert.equal(view(g,'s0').me.statementUsed,false);g.players[0].lastMessage=0;act(g,'s0',{type:'chat',text:'Eli is evil',statement:true});assert.equal(g.messages.at(-1).statement,true);});
test('statements must be in the Town square, by day, from a living player',()=>{const g=moonGame(['gossip','minstrel','tinker','assassin','zombuul'],NAMES);moonDay(g);assert.throws(()=>act(g,'s0',{type:'chat',text:'Dee is evil',statement:true,to:g.players[1].id}),/Town square/);act(g,'s0',{type:'group',title:'Plot',members:[g.players[1].id,g.players[2].id]});assert.throws(()=>act(g,'s0',{type:'chat',text:'Dee is evil',statement:true,group:g.groups[0].id}),/Town square/);g.players[1].alive=false;assert.throws(()=>act(g,'s1',{type:'chat',text:'Dee is evil',statement:true}),/living/);act(g,'s0',{type:'pause'});assert.throws(()=>act(g,'s0',{type:'chat',text:'Dee is evil',statement:true}),/active day/);act(g,'s0',{type:'pause'});g.phase='lobby';assert.throws(()=>act(g,'s0',{type:'chat',text:'Dee is evil',statement:true}),/active day/);});
test('anyone can bluff a statement, and a bluff never kills',()=>{const g=moonGame(['gossip','minstrel','tinker','assassin','zombuul'],NAMES);moonDay(g);act(g,'s3',{type:'chat',text:'Dee is evil',statement:true});assert.equal(g.messages.at(-1).statement,true);assert.equal(g.gossip,null);g.diedToday=true;g.drunks.push({id:g.players[2].id,until:99});beginNight(g);moonDay(g,q=>q.optional?'skip':null);assert(g.players.every(p=>p.alive));});
test('statements do not exist in Trouble Brewing',()=>{const g=daytime(game());assert.throws(()=>act(g,'s0',{type:'chat',text:'P1 is evil',statement:true}));});
test('Tinker can die during the day, at the chosen moment',()=>{const g=moonGame(['chambermaid','minstrel','tinker','assassin','zombuul']);moonDay(g);const at=Date.now()+5000;g.tinkerAt=at;assert.equal(tick(g,at-1),false);assert(g.players[2].alive);assert.equal(tick(g,at),true);assert(!g.players[2].alive);assert(g.events.some(e=>e.text==='P2 dies.'));assert(g.diedToday&&g.outsiderDied);assert.equal(g.tinkerAt,null);assert.equal(g.phase,'day');});
test('a drunk Tinker does not die, and a pause holds back the moment',()=>{const g=moonGame(['chambermaid','minstrel','tinker','assassin','zombuul']);moonDay(g);g.tinkerAt=1000;g.drunks.push({id:g.players[2].id,until:99});tick(g,2000);assert(g.players[2].alive);const h=moonGame(['chambermaid','minstrel','tinker','assassin','zombuul']);moonDay(h);const at=Date.now()+1000;h.tinkerAt=at;act(h,'s0',{type:'pause'});assert.equal(tick(h,at+1),false);assert(h.players[2].alive);act(h,'s0',{type:'pause'});assert(h.tinkerAt>=at);});
test('Tinker day death is scheduled only inside the day, and ends with it',()=>{let scheduled=0;repeat(600,()=>{const g=moonGame(['chambermaid','minstrel','tinker','assassin','zombuul']);moonDay(g);if(g.tinkerAt){scheduled++;assert(g.tinkerAt<=Date.now()+g.settings.daySeconds*1000+50);g.diedToday=true;beginNight(g);assert.equal(g.tinkerAt,null);}});assert(scheduled>0&&scheduled<150,`scheduled ${scheduled}`);});
test('Gossip: false claims read as false',()=>{for(const say of ['Ana is evil','Eli is the Fool','The Demon is Ana','There are two Outsiders','the Pukka is in play','nobody is the Zombuul','Ana and Bo are both evil','Dee is not a Minion'])assert.equal(gossipGame(say,NAMES).gossip.truth,false,say);});
test('Gossip: true claims in many forms',()=>{for(const say of ['Eli is the Zombuul','The Zombuul is Eli','the demon is eli','Eli is the demon','Ana is good','Ana and Bo are good','Ana, Bo and Cy are good','neither Dee nor Eli is good','either Ana or Eli is evil','exactly one of Ana and Eli is evil','at least one of Dee and Eli is evil','both Dee and Eli are evil','there is one Outsider','there is a Tinker','there are 2 evil players','at least two players are evil','there are no Pukka','the Pukka is not in play','Tinker is in play','the Assassin is next to Eli','Dee is next to the Demon','Dee sits beside Eli','a Minion is next to Eli','Cy has an evil neighbour','Bo\'s neighbours are both good','Eli\'s character is Zombuul','everyone is alive','someone is evil','no one is dead','I am good','I am the Gossip','Ana is alive','Dee is evil and Ana is good','Ana is evil or Dee is evil','Dee is evil but Ana is good','two players are evil'])assert.equal(gossipGame(say,NAMES).gossip.truth,true,say);});
test('Gossip: vague messages are refused and tell the Gossip why, without counting',()=>{for(const say of ['what do we think','I feel like someone is lying','Dee seems kinda sus','hello','Ana is evil because Bo said so']){const g=moonGame(['gossip','minstrel','tinker','assassin','zombuul'],NAMES);moonDay(g);assert.throws(()=>act(g,'s0',{type:'chat',text:say,statement:true}),/must be able to tell/);assert.equal(g.gossip,null);assert.equal(g.messages.length,0);assert.equal(view(g,'s0').me.statementUsed,false);}});
test('Gossip: names with spaces and odd punctuation still match',()=>{const g=gossipGame('Mary-Jane O\'Brien is GOOD',["Mary-Jane O'Brien",'Bo','Cy','Dee','Eli']);assert.equal(g.gossip.truth,true);});
test('Gossip: true means one death at night, and only for a working Gossip',()=>{const run=(say,drunk)=>{const g=gossipGame(say,NAMES);g.diedToday=true;g.drunks.push({id:g.players[2].id,until:99});if(drunk)g.drunks.push({id:g.players[0].id,until:99});beginNight(g);let n=0;while(g.pending&&n++<9){const q=g.pending;act(g,g.players.find(p=>p.id===q.id).session,{type:'night',key:q.key,skip:true});}return g.players.filter(p=>!p.alive).length;};assert.equal(run('Dee is evil'),1);assert.equal(run('Ana is evil'),0);assert.equal(run('Dee is evil',true),0);});
test('a reveal reports a Lunatic\'s belief and a turned Goon',()=>{const g=moonGame(['goon','minstrel','lunatic','assassin','zombuul']);moonDay(g);moonNext(g,q=>q.role==='zombuul'?[g.players[0]]:q.role==='assassin'?'skip':q.id===g.players[2].id?g.players.filter(p=>p!==g.players[2]).slice(0,q.count):null);g.players[4].zombuulSpent=true;kill(g,g.players[4],'execution');const v=view(g,'s0');assert.equal(g.winner,'good');assert.equal(v.players[2].initialRole,'lunatic');assert.notEqual(v.players[2].shown,'lunatic');assert.equal(v.players[0].evil,true);});
test('finished game reveals roles and policy audit, never session credentials',()=>{const g=daytime(game());g.poison=null;kill(g,g.players[4],'execution');const v=view(g,'s0');assert.equal(v.phase,'ended');assert(v.decisions.length);assert(v.players[4].role);assert(!JSON.stringify(v).includes('"session"'));});
const readyUp=(g,except=[])=>g.players.filter(p=>p.alive&&!except.includes(p)).forEach(p=>act(g,p.session,{type:'ready'},new Set(except.map(x=>x.id))));
test('offline players count as ready for dusk',()=>{const g=daytime(game()),afk=g.players.filter(p=>p.alive).at(-1);const day=g.day;readyUp(g,[afk]);assert.notEqual(g.phase,'day');assert.equal(g.day,day+1);});
test('an online player who has not readied still holds the day',()=>{const g=daytime(game()),afk=g.players.filter(p=>p.alive).at(-1);g.players.filter(p=>p.alive&&p!==afk).forEach(p=>act(g,p.session,{type:'ready'}));assert.equal(g.phase,'day');});
test('the last holdout going offline ends the day on the next poll',()=>{const g=daytime(game()),afk=g.players.filter(p=>p.alive).at(-1);g.players.filter(p=>p.alive&&p!==afk).forEach(p=>act(g,p.session,{type:'ready'}));assert.equal(tick(g),false);assert.equal(tick(g,Date.now(),new Set([afk.id])),true);assert.notEqual(g.phase,'day');});
test('a table where every living player is offline waits for the timer',()=>{const g=daytime(game());assert.equal(tick(g,Date.now(),new Set(g.players.filter(p=>p.alive).map(p=>p.id))),false);assert.equal(g.phase,'day');});
test('going offline does not cut a vote short',()=>{const g=daytime(game()),[a,b]=g.players.filter(p=>p.alive);act(g,a.session,{type:'nominate',target:b.id});assert.equal(tick(g,Date.now(),new Set(g.players.filter(p=>p!==a).map(p=>p.id))),false);assert(g.nomination);});
test('a night choice nobody makes within 30 seconds of seeing it is made by the Storyteller, who says so',()=>{
 const g=game(),q=g.pending,t0=Date.now();assert.equal(q.role,'poisoner');
 assert.equal(seen(g,'s0',t0),false);assert.equal(g.pending.deadline,undefined);
 assert.equal(seen(g,'s3',t0),true);assert.equal(g.pending.deadline,t0+30000);assert.equal(seen(g,'s3',t0+5000),false);
 assert.equal(tick(g,t0+29000),false);assert.equal(g.pending?.key,q.key);
 assert.equal(tick(g,t0+30000),true);assert.notEqual(g.pending?.key,q.key);
 assert(g.players[3].inbox.some(i=>/did not choose in time, so the Storyteller chose/.test(i.text)));
 assert(g.choices.some(c=>c.role==='poisoner'&&c.auto&&c.targets.length===1));
});
test('an offline player’s night choice is made at once, and a prompt nobody has seen does not time out',()=>{
 const g=game();assert.equal(tick(g,Date.now()+120000),false);assert(g.pending);
 assert.equal(tick(g,Date.now(),new Set([g.players[3].id])),true);assert.equal(g.pending,null);assert.equal(g.phase,'night');assert(g.dawnAt);
});
test('a timed-out Demon never attacks itself or its own team',()=>{repeat(60,()=>{
 const g=daytime(game(['chef','monk','slayer','poisoner','imp']));beginNight(g);
 while(g.pending&&g.pending.role!=='imp')choose(g,[0]);
 assert.equal(g.pending.role,'imp');tick(g,Date.now(),new Set([g.players[4].id]));
 assert.equal(g.players[4].role,'imp');assert(g.players[4].alive);assert(g.players[3].alive);
});});
test('dawn always comes 5–15 seconds after the last night choice, even when nobody wakes',()=>{repeat(40,()=>{
 const t=Date.now(),g=game(['chef','soldier','saint','recluse','imp']);
 assert.equal(g.phase,'night');assert.equal(g.pending,null);
 assert(g.dawnAt>=t+5000&&g.dawnAt<=Date.now()+15000,`dawn in ${g.dawnAt-t}ms`);
 assert.equal(tick(g,g.dawnAt-1),false);assert.equal(g.phase,'night');
 assert.equal(tick(g,g.dawnAt),true);assert.equal(g.phase,'day');
});});
test('a Butler can only raise their hand while their master’s is up, and it comes down with theirs',()=>{
 const g=daytime(game(['butler','soldier','slayer','poisoner','imp'])),[butler,master]=g.players;butler.master=master.id;
 act(g,'s2',{type:'nominate',target:g.players[4].id});const n=g.nomination.id,vote=(s,yes)=>act(g,s,{type:'vote',nomination:n,yes});
 assert.throws(()=>vote('s0',true),/master/);
 vote('s1',true);vote('s0',true);assert.equal(g.nomination.hands[butler.id],true);
 vote('s1',false);assert.equal(g.nomination.hands[butler.id],false);
 vote('s1',true);vote('s0',true);vote('s2',true);tick(g,g.nomination.deadline);
 assert.equal(g.ballots.at(-1).count,3);
});
test('a majority can end the game and reveal every character, with no winner',()=>{
 const g=daytime(game());act(g,'s1',{type:'propose',kind:'reveal'});assert(g.proposal);
 assert.throws(()=>act(g,'s2',{type:'propose',kind:'lobby'}));
 act(g,'s2',{type:'proposal_vote',proposal:g.proposal.id,yes:true});assert.equal(g.phase,'day');
 act(g,'s3',{type:'proposal_vote',proposal:g.proposal.id,yes:true});
 assert.equal(g.phase,'ended');assert.equal(g.winner,null);assert(g.called);
 const v=view(g,'s0');assert(v.called);assert(v.players.every(p=>p.role));
});
test('a vote to end the game fails without a majority or after a minute, and offline players are not counted',()=>{
 const g=daytime(game());act(g,'s1',{type:'propose',kind:'lobby'});
 for(const s of ['s2','s3','s4'])act(g,s,{type:'proposal_vote',proposal:g.proposal.id,yes:false});
 assert.equal(g.proposal,null);assert.equal(g.phase,'day');assert.throws(()=>act(g,'s1',{type:'propose',kind:'lobby'}),/recently/);
 act(g,'s2',{type:'propose',kind:'reveal'});assert.equal(tick(g,g.proposal.deadline),true);assert.equal(g.proposal,null);assert.equal(g.phase,'day');
 const away=new Set([g.players[1].id,g.players[4].id]);
 act(g,'s3',{type:'propose',kind:'lobby'},away);assert(g.proposal);
 act(g,'s0',{type:'proposal_vote',proposal:g.proposal.id,yes:true},away);assert.equal(g.phase,'lobby');
});
test('spectators can watch at any time, see only public things, and cannot take part',()=>{
 const g=daytime(game());assert.throws(()=>join(g,'Late','late'));spectate(g,'Watcher','w');
 act(g,'s0',{type:'chat',text:'hello town'});g.players[0].lastMessage=0;act(g,'s0',{type:'chat',text:'psst',to:g.players[1].id});
 const v=view(g,'w');assert(v.me.spectator);assert.deepEqual(v.messages.map(m=>m.text),['hello town']);
 assert(v.players.every(p=>!('role' in p)));assert.equal(v.me.inbox.length,0);assert.equal(v.pending,null);assert.deepEqual(v.groups,[]);
 for(const type of ['chat','ready','vote','nominate','propose','claim'])assert.throws(()=>act(g,'w',{type,text:'hi',kind:'lobby'}),/Spectators/);
 assert.deepEqual(view(g,'s1').spectators,['Watcher']);assert.throws(()=>spectate(g,'P1','x'),/taken/);
 act(g,'w',{type:'leave'});assert.throws(()=>view(g,'w'));
});
test('a spectator can take a seat in the lobby, and spectators stay for the next game',()=>{
 const g=newGame('ABCDEFGH','A','a');spectate(g,'W','w');join(g,'W','w');assert.equal(g.spectators.length,0);assert(g.players.some(p=>p.session==='w'));
 const h=game();spectate(h,'V','v');voteToLobby(h);assert.equal(view(h,'v').me.spectator,true);
});
test('the end-of-game log shows night choices and what each player was told, in order, and never whispers',()=>{
 const g=daytime(game(['empath','soldier','slayer','poisoner','imp']));
 act(g,'s0',{type:'chat',text:'secret plan',to:g.players[1].id});
 assert.equal(view(g,'s0').timeline,undefined);
 act(g,'s1',{type:'propose',kind:'reveal'});for(const s of ['s2','s3'])act(g,s,{type:'proposal_vote',proposal:g.proposal.id,yes:true});
 const tl=view(g,'s0').timeline;
 assert(tl.some(r=>r.kind==='choice'&&r.by==='P3'&&r.role==='poisoner'&&r.targets.length===1));
 assert(tl.some(r=>r.kind==='told'&&r.to==='P0'));assert(tl.some(r=>r.kind==='event'));
 assert(!JSON.stringify(tl).includes('secret plan'));assert(!tl.some(r=>/^Your choice/.test(r.text||'')));
 assert(tl.every((r,i)=>!i||tl[i-1].n<=r.n));
});
